 {'library_sha256'=>o+'/candidate-library/libkujo-0204a58eed7d01d2.rlib','binary_sha256'=>o+'/candidate-kujo','artifacts_sha256'=>o+'/normal-release-artifacts.jsonl','compiler_log_sha256'=>o+'/normal-release.log'}.each{|k,p|raise 'Normal artifact provenance drift' unless a[k]==Digest::SHA256.file(p).hexdigest}
end
