raise 'Contracts' unless r.fetch('contracts').map{|x|x['argv']}.sort==contracts.sort&&r['contracts'].all?{|x|x['exit']==0&&x['stdout']=="STRING BATCH CONTRACT PASS\n"}
regressions=r['rows'].select{|x|%w[requests bytes].any?{|m|x[m]>x['baseline'][m]}}
raise 'Regression list' unless regressions==r['regressions']
slopes=r['rows'].group_by{|x|x['baseline'].values_at('shape','width','snapshot','mode')}.map do |group,rows|
 a,b=rows.sort_by{|x|x['baseline']['calls']}.last(2)
 {'group'=>group,'bytes'=>(b['bytes']-a['bytes'])/16.0,'requests'=>(b['requests']-a['requests'])/16.0,'baseline_bytes'=>(b['baseline']['bytes']-a['baseline']['bytes'])/16.0,'baseline_requests'=>(b['baseline']['requests']-a['baseline']['requests'])/16.0}
end
raise 'Slope data' unless slopes==r['slopes']&&slopes.size==96
