raise 'Slope regressions' unless bad_slopes==r['slope_regressions']
passed=regressions.empty?&&bad_slopes.empty?
raise 'Incorrect status' unless (r['status']=='passed')==passed
if passed
 %w[vm jit].each do |mode|
  target=slopes.select{|x|x['group'][0]=='string-first'&&x['group'][2]=='once'&&x['group'][3]==mode}
  raise 'String-first target still scales' unless target.size==4&&target.map{|x|x['bytes']}.uniq.size==1
  raise 'String-first improvement absent' unless target.select{|x|[8,2048].include?(x['group'][1])}.all?{|x|x['bytes']<x['baseline_bytes']}
 end
